CREATE TABLE public.topic_reading_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,page_key text NOT NULL,status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','succeeded','failed')),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,page_key));
GRANT SELECT ON public.topic_reading_jobs TO authenticated;
GRANT ALL ON public.topic_reading_jobs TO service_role;
ALTER TABLE public.topic_reading_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners read reading jobs" ON public.topic_reading_jobs FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE FUNCTION public.claim_topic_reading_job(p_owner_id uuid,p_page_key text,p_regenerate boolean DEFAULT false) RETURNS TABLE(job_id uuid,job_status text,claimed boolean,quota_exceeded boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.topic_reading_jobs%ROWTYPE; n integer; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(p_owner_id::text,0)); SELECT * INTO j FROM public.topic_reading_jobs WHERE owner_id=p_owner_id AND page_key=p_page_key FOR UPDATE; IF FOUND AND j.status='running' AND j.updated_at>now()-interval '5 minutes' THEN RETURN QUERY SELECT j.id,j.status,false,false; RETURN; END IF; IF FOUND AND j.status='succeeded' AND NOT p_regenerate THEN RETURN QUERY SELECT j.id,j.status,false,false; RETURN; END IF; SELECT count(*) INTO n FROM public.ai_usage WHERE user_id=p_owner_id AND feature='topic-reading' AND created_at>=now()-interval '24 hours'; IF n>=50 THEN RETURN QUERY SELECT NULL::uuid,NULL::text,false,true; RETURN; END IF; INSERT INTO public.ai_usage(user_id,feature) VALUES(p_owner_id,'topic-reading'); INSERT INTO public.topic_reading_jobs(owner_id,page_key,status) VALUES(p_owner_id,p_page_key,'running') ON CONFLICT(owner_id,page_key) DO UPDATE SET status='running',updated_at=now() RETURNING * INTO j; RETURN QUERY SELECT j.id,j.status,true,false; END $$;
REVOKE ALL ON FUNCTION public.claim_topic_reading_job(uuid,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_topic_reading_job(uuid,text,boolean) TO service_role;